// Filter leads needing follow-up
const now = new Date();
const leads = $items();

const needsFollowup = leads.filter(item => {
  const lead = item.json;

  // Skip booked, unqualified, or handoff
  if (['booked', 'unqualified', 'handoff'].includes(lead.status)) {
    return false;
  }

  // Check if follow-up is due
  if (!lead.next_followup_at) return false;

  const followupDate = new Date(lead.next_followup_at);
  return followupDate <= now;
});

return needsFollowup;

// Prepare follow-up message request
const lead = $json;
const configItems = $items('Get Config');

// Convert config to object
const config = {};
configItems.forEach(item => {
  config[item.json.key] = item.json.value;
});

// Determine follow-up day
let followupDay = 'Day 1';
const lastContact = new Date(lead.last_message_at);
const daysSince = Math.floor((Date.now() - lastContact) / (1000 * 60 * 60 * 24));

if (daysSince >= 7) followupDay = 'Day 7 (final)';
else if (daysSince >= 3) followupDay = 'Day 3';

const systemPrompt = 'You are a friendly follow-up assistant for a pool cleaning company. Generate short, non-pushy follow-up messages. Output valid JSON only with a reply_text field.';

const userMessage = `Generate a ${followupDay} follow-up for this lead:\n${JSON.stringify(lead)}\n\nKeep it brief and friendly.`;

return [{
  json: {
    lead,
    config,
    systemPrompt,
    userMessage,
    followupDay
  }
}];

// Parse follow-up response
const response = $json;
const prepData = $node['Prepare Follow-up'].json;
let replyText;

try {
  const text = response.content[0].text;
  const parsed = JSON.parse(text);
  replyText = parsed.reply_text;
} catch (e) {
  // Fallback messages
  const fallbacks = {
    'Day 1': "Just checking in — happy to get you a quote or answer questions about pool service.",
    'Day 3': "We have a few openings this week if you want to get started with pool cleaning.",
    'Day 7 (final)': "No pressure — just let me know if you'd like help with your pool!"
  };
  replyText = fallbacks[prepData.followupDay] || fallbacks['Day 1'];
}

// Calculate next follow-up
let nextFollowup = null;
if (prepData.followupDay === 'Day 1') {
  nextFollowup = new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString();
} else if (prepData.followupDay === 'Day 3') {
  nextFollowup = new Date(Date.now() + 4 * 24 * 60 * 60 * 1000).toISOString();
}

return [{
  json: {
    reply_text: replyText,
    lead: prepData.lead,
    config: prepData.config,
    next_followup_at: nextFollowup,
    is_final: prepData.followupDay === 'Day 7 (final)'
  }
}];
